contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address logger, bool status, address keepAddr) public {
        require(logger != address(this));

        // Before approval, the unapproved caller (this contract) gets false.
        bool r1 = c.logCreated(keepAddr);
        assert(!r1);

        // Owner (this contract, since it deployed c) sets approval status.
        c.setApprovedLogger(logger, status);

        bool before = c.approvedLoggers(logger);
        if (status) {
            assert(before);
        } else {
            assert(!before);
        }

        // Unapproved unrelated caller still rejected: a fresh address not approved.
        bool r2 = c.logCreated(keepAddr);
        assert(r2 == c.approvedLoggers(address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address keepAddr, bytes32 digest) public {
        // Before approval, logging calls must fail.
        bool rBefore = c.logCreated(keepAddr);

        // Owner (this contract deployed c) approves this contract as a logger.
        c.setApprovedLogger(address(this), true);

        bool approved = c.approvedToLog(address(this));
        bool rAfter = c.logCreated(keepAddr);
        bool rSig = c.logGotRedemptionSignature(digest, bytes32(0), bytes32(0));

        assert(approved && !rBefore && rAfter && rSig);
    }
    receive() external payable {}
}
